head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;
scwin.gDutyID = js_duty;
scwin.vScrenID = 'ULDSTF31010.xml';
scwin.gNowDutyYn = '';
scwin.gNowDutyStat = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (scwin.gLdMktTp != '9') {
        $c.stf.showObj(panel_mkt, false);
    }

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue(vCurDate); // 현재날짜
    edt_EDATE.setValue(vCurDate); // 현재날짜

    dts_CodeChrgEmpNo.DataID = "/CodeAction.do?method=listEmpNo&DEP_CD=" + js_dep_cd + "&TEAM_ID=" + js_team + "&ROLL_CD=09&For=R";
    dts_CodeChrgEmpNo.Reset();
    dts_CodeEmpNo.DataID = "/CodeAction.do?method=listEmpNo&DEP_CD=" + js_dep_cd + "&TEAM_ID=" + js_team + "&ROLL_CD=03&For=R";
    dts_CodeEmpNo.Reset();
    for (var i = 1; i <= dts_CodeEmpNo.getTotalRow(); i++) {
        if ("" != dts_CodeEmpNo.getCellData(i, 1)) {
            dts_CodeChrgEmpNo.insertRow();
            var crow = dts_CodeChrgEmpNo.getTotalRow();
            dts_CodeChrgEmpNo.setCellData(crow, "VALUE", dts_CodeEmpNo.getCellData(i, 1));
            dts_CodeChrgEmpNo.setCellData(crow, "TEXT", dts_CodeEmpNo.getCellData(i, 2));
        }
    }
    dts_CodeChrgEmpNo.setRowPosition(1, 0);
    scwin.fn_setTime();
};


//조회 버튼
scwin.fn_setTime = function() {
    /*
    serverTime =	frame.Provider("/top").serverYear+ "년" +
    						frame.Provider("/top").serverMonth+ "월" +
    						frame.Provider("/top").serverDay+ "일" +
    						frame.Provider("/top").serverHours +
    						frame.Provider("/top").displayTime(frame.Provider("/top").serverMinutes) +
    						frame.Provider("/top").displayTime(frame.Provider("/top").serverSeconds);
    setObjectValue(txa_step_3,  serverTime);
    */
    var vCurDate = $c.ut.cGetToday("yyyy-mm-dd hh:mm:ss");
    $c.stf.setObjectValue(txb_now, "현재시각 : " + vCurDate);
    scwin.runClock();
};
scwin.runClock = function() {
    setTimeout("fn_setTime()", 1000);
};


//조회 버튼
scwin.fn_HistorySearch = function() {
    var url = "/PersonOnDuty.do?method=searchDisclsDutyHistory";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID); //시장구분
    url += "&ChrgEmpNo=" + $c.stf.getObjectValue(cmb_ChrgEmpNo);
    url += "&EmpNo=" + $c.stf.getObjectValue(cmb_EmpNo);
    url += "&SDate=" + $c.stf.getObjectValue(edt_SDATE);
    url += "&EDate=" + $c.stf.getObjectValue(edt_EDATE);
    if (js_dep_cd == "2430") {
        url += "&GDUTY=";
    } else {
        url += "&GDUTY=" + js_gduty;
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_OneSearch = function() {
    setTimeout("fn_OneSearch()", 60000); // 1초 = 1000 , 60초 = 60000

    var url = "/PersonOnDuty.do?method=searchDisclsDutyOneHistory";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID); //시장구분
    if (js_dep_cd == "2430") {
        url += "&GDUTY=";
    } else {
        url += "&GDUTY=" + js_gduty;
    }
    url += "&EmpNo=" + js_emp_no;
    dts_OneGrid.DataID = encodeURI(url);
    dts_OneGrid.Reset();
    $c.cm.ShowWin(grd_OneGrid);
};
scwin.fn_CheckStatus = function() {
    $c.stf.fn_checkDutyTimeStatus(js_emp_no, '', dts_DutyStatus); //fn_checkDutyTimeStatus(pEmpNo, pAcptNo, pDtsObj) 

};


/*
   당번업무 시작 및 마감 처리
   - 1 : 당번업무 시작
   - 2 : 당번업무 마감
 */
scwin.fn_CloseProcess = function(pCloseStep) {
    scwin.fn_CheckStatus();
    if (scwin.gNowDutyYn != 'Y') {
        $c.win.alert("금일당번만 선택할 수 있습니다.");
        return;
    }
    if (scwin.gNowDutyStat == 'S' && pCloseStep == 'S') {
        $c.win.alert("현재 당번업무 시작 상태입니다.");
        return;
    }
    if (scwin.gNowDutyStat == 'E' && pCloseStep == 'E') {
        $c.win.alert("현재 당번업무 마감 상태입니다.");
        return;
    }
    if (scwin.gNowDutyStat == 'N' && pCloseStep == 'E') {
        $c.win.alert("먼저 당번업무 시작부터 하시기 바랍니다.");
        return;
    }
    dts_CloseProcs.removeAll();
    dts_CloseProcs.insertRow();
    dts_CloseProcs.setCellData(1, "SEQ", scwin.gEmpNo);
    dts_CloseProcs.setCellData(1, "INTEG_USR_ID", scwin.gEmpNo);
    dts_CloseProcs.setCellData(1, "BZ_STRT_CLS_TP_CD", pCloseStep);
    var vProcMsg = "";
    if (pCloseStep == 'S') {
        vProcMsg = "당번업무 시작";
    } else if (pCloseStep == 'E') {
        vProcMsg = "당번업무 마감";
    }
    var vAnswer = confirm($c.stf.getMessageParam("MSG-A006", vProcMsg));
    if (vAnswer == true) {
        trs_CloseProcs.Action = "/PersonOnDuty.do?method=registerDisclsDutyHistory&inputMessageId=PERSONONDUTY_HISTORY_IN&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_CloseProcs.KeyName = "toinb_dataid4";
        trs_CloseProcs.KeyValue = "JSP(I:pInput=dts_CloseProcs)";
        trs_CloseProcs.Post();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_HistorySearch(); //조회 버튼

};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.dts_OneGrid_OnLoadError = function() {
    $c.stf.alert_error(dts_OneGrid);
};
scwin.dts_DutyStatus_OnLoadError = function() {
    $c.stf.alert_error(dts_DutyStatus);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page); //총 건수
    $c.cm.CloseWin(rowcount, grd_Grid); //조회완료시 LOADING 이미지 종료

};
scwin.dts_OneGrid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_OneGrid); //조회완료시 LOADING 이미지 종료

};
scwin.dts_DutyStatus_OnLoadCompleted = function(rowcount) {
    scwin.gNowDutyYn = dts_DutyStatus.getCellData(1, 'NOW_DUTY_YN');
    scwin.gNowDutyStat = dts_DutyStatus.getCellData(1, 'NOW_DUTY_STAT');
};
scwin.trs_CloseProcs_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", ""));
    scwin.fn_OneSearch();
};
scwin.trs_CloseProcs_OnFail = function() {
    $c.win.alert('trs_CloseProcs.OnFail() :' + trs_CloseProcs.ErrorMsg);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.stf.getObjectValue(cmb_PeriodTp);
    $c.stf.fn_setFromToDate(vTp, edt_SDATE, edt_EDATE); //기간선택 콤보박스

};
scwin.btn_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE); //공시일자-시작일 이미지 버튼 클릭 시 달력 팝업

};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE); //공시일자-종료일 이미지 버튼 클릭 시 달력 팝업

};
scwin.btn_Excel_onclick = function() {
    $c.data.downloadGridViewExcel(grd_Grid, "공시당번이력조회", "", "8");
};
scwin.btn_duty_start_onclick = function() {
    scwin.fn_CloseProcess('S');
};
scwin.btn_duty_close_onclick = function() {
    scwin.fn_CloseProcess('E');
};
scwin.MxTab_1_OnSelChanged = function(nIndex) {
    if (MxTab_1.getSelectedTabIndex() == 1) {
        scwin.fn_OneSearch();
    } else if (MxTab_1.getSelectedTabIndex() == 2) {
        scwin.fn_HistorySearch();
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_3); // 검색조건 패널에 스타일 적용

    $c.stf.setObjectValue(txb_EMP_NM, js_emp_nm);
    scwin.fn_SetCode();

    // 가우스헤더 셋팅
    dts_CloseProcs.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=PERSONONDUTY_HISTORY_IN";
    dts_CloseProcs.reset();
    scwin.fn_OneSearch();
};
